const DESTINATION_KEY = "tds-last-destination";
const DESTINATIONS_STORAGE_KEY = "tds-destinations";
const WEBHOOK_URL_PATTERN = /^https:\/\/discord\.com\/api\/webhooks\/\d+\/[\w-]+$/i;
const TOAST_DURATION_MS = 4000;

const DISCORD_LIMITS = { content: 2000 };
const MESSAGE_CHUNK_LIMIT = 1900;
const DISCORD_EMBED_LIMITS = {
  embedsPerMessage: 10,
  description: 4096,
  fieldName: 256,
  fieldValue: 1024,
  fieldsPerEmbed: 25,
  authorName: 256,
  title: 256,
  footer: 2048,
  totalEmbedChars: 6000
};
const EMBED_COLOR_MAIN = 0x1da1f2;
const EMBED_COLOR_QUOTE = 0x536471;
// Discord rejects webhook usernames containing "discord" (case-insensitive).
const WEBHOOK_SENDER_NAME = "Tweet Share";
// Self-hosted in repo so Discord's servers can fetch it reliably (Wikimedia often fails).
const WEBHOOK_SENDER_AVATAR_URL =
  "https://raw.githubusercontent.com/itsreverence/tweet-share/master/assets/webhook-avatar-v2.png";
const WEBHOOK_SEND_DELAY_MS = 750;
const CACHE_MAX_ENTRIES = 300;

const VIDEO_VARIANT_CACHE = new Map();
const TEXT_CUT_OFF_NOTE = "[Post cut off. Open on X for the rest.]";
const TWEET_CACHE = new Map();
const USER_CACHE = new Map();

function trimCache(cache, maxEntries = CACHE_MAX_ENTRIES) {
  while (cache.size > maxEntries) {
    const oldestKey = cache.keys().next().value;
    cache.delete(oldestKey);
  }
}

  // --- 00-theme.js ---
// Colors are RGB tuples ("231 233 234"), the format X publishes on :root (e.g. --color-text).
const TDS_FONT = 'TwitterChirp, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';
const TDS_RGB_PATTERN = /^\d+\s+\d+\s+\d+$/;

// X's colours, moved only as far as needed for 4.5:1 on every background each one meets, hover tints included:
// subtle (muted text), link (blue text), danger and success (red and green text and icons), and accent (filled under white text).
const THEME_PALETTES = {
  light: {
    surface: "255 255 255", raised: "247 249 249", text: "15 20 25", subtle: "83 100 113", border: "207 217 222", shadow: "101 119 134",
    link: "12 113 181", danger: "210 10 23", success: "0 132 88", accent: "13 120 192"
  },
  dim: {
    surface: "21 32 43", raised: "30 39 50", text: "247 249 249", subtle: "139 152 165", border: "56 68 77", shadow: "255 255 255",
    link: "29 155 240", danger: "247 89 99", success: "0 186 124", accent: "13 120 192"
  },
  dark: {
    surface: "0 0 0", raised: "22 24 28", text: "231 233 234", subtle: "125 131 136", border: "47 51 54", shadow: "255 255 255",
    link: "29 155 240", danger: "244 33 46", success: "0 186 124", accent: "13 120 192"
  }
};
// The blue of focus rings and borders, which carry no text.
const THEME_ACCENTS = { blue: "29 155 240" };
// The page background picks the palette. X's variables refine only its text colour and that blue,
// so none of them can pull a colour text is drawn in or on below 4.5:1.
const X_THEME_VARIABLES = {
  text: "--color-text",
  blue: "--color-blue"
};

function themeNameForBackground([red, green, blue]) {
  const luminance = (0.299 * red + 0.587 * green + 0.114 * blue) / 255;
  if (luminance > 0.55) return "light";
  return luminance > 0.06 ? "dim" : "dark";
}

// `variables` holds the X tokens the page defines; `pageBackground` is [r, g, b] or null.
function resolveTheme({ variables = {}, pageBackground = null } = {}) {
  const palette = THEME_PALETTES[pageBackground ? themeNameForBackground(pageBackground) : "dark"];
  return { ...palette, ...THEME_ACCENTS, ...variables };
}

function pageBackgroundRgb() {
  for (const node of [document.body, document.documentElement]) {
    if (!node) continue;
    const match = /^rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)$/.exec(getComputedStyle(node).backgroundColor);
    if (match && Number(match[4] ?? 1) > 0) return match.slice(1, 4).map(Number);
  }
  return null;
}

function readThemeEnvironment() {
  const rootStyle = getComputedStyle(document.documentElement);
  const variables = {};
  for (const [token, name] of Object.entries(X_THEME_VARIABLES)) {
    const value = rootStyle.getPropertyValue(name).trim();
    if (TDS_RGB_PATTERN.test(value)) variables[token] = value;
  }
  return { variables, pageBackground: pageBackgroundRgb() };
}

function relativeLuminance([red, green, blue]) {
  const linear = (channel) => {
    const value = channel / 255;
    return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * linear(red) + 0.7152 * linear(green) + 0.0722 * linear(blue);
}

function hslToRgb(hue, saturation, lightness) {
  const chroma = (saturation / 100) * Math.min(lightness / 100, 1 - lightness / 100);
  const channel = (offset) => {
    const k = (offset + hue / 30) % 12;
    return Math.round(255 * (lightness / 100 - chroma * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return [channel(0), channel(8), channel(4)];
}

// Yellows and greens are bright at any given lightness, so each hue darkens only until white initials reach 4.5:1.
function avatarColor(hue) {
  let rgb;
  for (let lightness = 45; lightness > 0; lightness -= 1) {
    rgb = hslToRgb(hue, 60, lightness);
    if (1.05 / (relativeLuminance(rgb) + 0.05) >= 4.5) break;
  }
  return `rgb(${rgb.join(" ")})`;
}

function applyXThemeVars(element) {
  for (const [token, value] of Object.entries(resolveTheme(readThemeEnvironment()))) {
    element.style.setProperty(`--tds-${token}`, value);
  }
}

function tdsSharedSurfaceCss() {
  return `
    .${POPOVER_CLASS},
    .${TOAST_CLASS},
    .${SETTINGS_CLASS}__dialog {
      background: rgb(var(--tds-surface));
      border: 1px solid rgb(var(--tds-border));
      box-shadow: rgb(var(--tds-shadow) / 0.2) 0 0 15px, rgb(var(--tds-shadow) / 0.15) 0 0 3px 1px;
      color: rgb(var(--tds-text));
      font-family: ${TDS_FONT};
    }
  `;
}

  // --- 01-http.js ---
function xhrClient() {
  return typeof GM !== "undefined" && GM.xmlHttpRequest ? GM.xmlHttpRequest : GM_xmlhttpRequest;
}

const HTTP_TIMEOUT_MS = 15_000;
const HTTP_MAX_RATE_LIMIT_RETRIES = 2;
const HTTP_DEFAULT_RETRY_DELAY_MS = 1_000;
const HTTP_MAX_RETRY_DELAY_MS = 10_000;

function parseDiscordResponse(response) {
  const text = response.responseText || "{}";
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    json = { raw: text };
  }

  if (response.status >= 200 && response.status < 300) {
    return json;
  }

  const detail = json.message || json.error || text.slice(0, 200);
  const error = new Error(detail || `Request returned ${response.status}`);
  error.status = response.status;
  const retryAfterSeconds = Number(json.retry_after);
  if (response.status === 429 && Number.isFinite(retryAfterSeconds) && retryAfterSeconds >= 0) {
    error.retryAfterMs = Math.ceil(retryAfterSeconds * 1000);
  }
  throw error;
}

function boundedRetryDelay(error) {
  const requested = Number(error?.retryAfterMs);
  const delayMs = Number.isFinite(requested) && requested >= 0 ? requested : HTTP_DEFAULT_RETRY_DELAY_MS;
  return delayMs <= HTTP_MAX_RETRY_DELAY_MS ? delayMs : null;
}

async function retryRateLimitedRequest(send, maxRetries = HTTP_MAX_RATE_LIMIT_RETRIES) {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await send();
    } catch (error) {
      if (error?.status !== 429 || attempt >= maxRetries) throw error;
      const retryDelayMs = boundedRetryDelay(error);
      if (retryDelayMs === null) throw error;
      await delay(retryDelayMs);
    }
  }
}

function requestOnce(method, url, body) {
  return new Promise((resolve, reject) => {
    xhrClient()({
      method,
      url,
      timeout: HTTP_TIMEOUT_MS,
      headers: { "content-type": "application/json" },
      data: body ? JSON.stringify(body) : undefined,
      onload(response) {
        try {
          resolve(parseDiscordResponse(response));
        } catch (error) {
          reject(error);
        }
      },
      onerror() {
        reject(new Error("Could not reach Discord. Check your network and webhook URL."));
      },
      ontimeout() {
        reject(new Error("The request timed out. Check your network and try again."));
      }
    });
  });
}

function request(method, url, body) {
  return retryRateLimitedRequest(() => requestOnce(method, url, body));
}

function requestMultipartOnce(url, payloadJson, files = []) {
  return new Promise((resolve, reject) => {
    const formData = new FormData();
    formData.append("payload_json", JSON.stringify(payloadJson || {}));
    files.forEach((file, index) => {
      const blob = file.blob || new Blob([file.bytes], { type: file.contentType || "application/octet-stream" });
      formData.append(file.name || `files[${index}]`, blob, file.filename || `media_${index}`);
    });

    xhrClient()({
      method: "POST",
      url,
      timeout: HTTP_TIMEOUT_MS,
      data: formData,
      onload(response) {
        try {
          resolve(parseDiscordResponse(response));
        } catch (error) {
          reject(error);
        }
      },
      onerror() {
        reject(new Error("Could not reach Discord. Check your network and webhook URL."));
      },
      ontimeout() {
        reject(new Error("The request timed out. Check your network and try again."));
      }
    });
  });
}

function requestMultipart(url, payloadJson, files = []) {
  return retryRateLimitedRequest(() => requestMultipartOnce(url, payloadJson, files));
}

function delay(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

  // --- 02-utils.js ---
function truncate(value, limit) {
  const textValue = String(value || "").trim();
  if (textValue.length <= limit) return textValue;
  const suffix = "...";
  if (limit <= suffix.length) return suffix.slice(0, Math.max(0, limit));
  return `${textValue.slice(0, limit - suffix.length).trimEnd()}${suffix}`;
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function absoluteUrl(url) {
  try {
    return new URL(url, location.href).toString();
  } catch {
    return "";
  }
}

function normalizeTweetUrl(url) {
  const parsed = new URL(url, location.href);
  parsed.hostname = "x.com";
  parsed.search = "";
  parsed.hash = "";
  parsed.pathname = parsed.pathname.replace(/(\/status\/\d+).*/, "$1");
  return parsed.toString();
}

function tweetIdFromUrl(url) {
  return String(url || "").match(/\/status\/(\d+)/)?.[1] || "";
}

function highResolutionProfileImageUrl(url) {
  return (url || "").replace(/_normal(\.(?:jpg|jpeg|png|webp))(?:\?|$)/i, "$1");
}

function isTweetImageMediaUrl(url) {
  const value = String(url || "");
  return /^https:\/\/pbs\.twimg\.com\/media\//i.test(value)
    && !/(?:\.svg(?:[?:]|$)|[?&]format=svg\b|:svg(?:\?|$))/i.test(value);
}

function highResolutionTweetImageUrl(url) {
  if (!isTweetImageMediaUrl(url)) return url;
  const base = url.split("?")[0].replace(/:(?:small|medium|large|orig|thumb)$/i, "");
  return `${base}?format=jpg&name=orig`;
}

function discordEmbedTimestamp(createdAt) {
  const raw = String(createdAt || "").trim();
  if (!raw) return undefined;
  const date = new Date(raw);
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString();
}

// X's API escapes these three in post text.
function decodeHtmlEntities(value) {
  return String(value || "").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
}

function isPlayableTweetVideoUrl(url) {
  return /^https:\/\/video\.twimg\.com\/.+\.mp4(?:\?|$)/.test(url || "") && !/\/aud\//.test(url || "");
}

function normalizeTweetVideoUrl(url) {
  if (!url) return "";
  return url.replace(/\/vid\/([^/]+)\/0\/0\/(\d+x\d+)\//, "/vid/$1/$2/");
}

function isTweetVideoPosterUrl(url) {
  return /^https:\/\/pbs\.twimg\.com\/.+\.(?:jpg|jpeg|png|webp)(?:\?|$)/.test(url || "");
}

function isTweetVideoThumbnailUrl(url) {
  return /^https:\/\/pbs\.twimg\.com\/(?:amplify_video_thumb|ext_tw_video_thumb|tweet_video_thumb)\//.test(url || "");
}

function posterMediaId(url) {
  return (url || "").match(/\/(?:amplify_video_thumb|ext_tw_video_thumb|tweet_video_thumb)\/(\d+)\//)?.[1] || "";
}

function videoQualityScore(url) {
  if (/\/amplify_video\/|\/ext_tw_video\//.test(url)) return 2_000_000_000;
  if (/\/vid\//.test(url)) return 1_000_000_000;
  if (/\/tweet_video\//.test(url)) return 500_000_000;

  const resolution = url.match(/\/(\d+)x(\d+)\//);
  if (resolution) {
    return Number(resolution[1]) * Number(resolution[2]);
  }

  const bitrate = url.match(/[?&](?:bitrate|br)=(\d+)/i) || url.match(/_(\d+)\.mp4(?:\?|$)/i);
  return bitrate ? Number(bitrate[1]) : 0;
}

function compareTweetVideoQuality(left, right) {
  return videoQualityScore(right) - videoQualityScore(left);
}

function playableVideoVariants(variants = []) {
  return variants
    .map((variant) => ({
      url: normalizeTweetVideoUrl(variant.url || variant.src || ""),
      bitrate: variant.bitrate || 0,
      type: variant.content_type || variant.type || ""
    }))
    .filter((variant) => variant.type === "video/mp4" && isPlayableTweetVideoUrl(variant.url))
    .filter((variant, index, all) => all.findIndex((candidate) => candidate.url === variant.url) === index)
    .sort((left, right) => (right.bitrate || videoQualityScore(right.url)) - (left.bitrate || videoQualityScore(left.url)));
}

function bestPlayableVideoVariantUrl(variants = []) {
  return playableVideoVariants(variants)[0]?.url || "";
}

function uniqueMedia(items) {
  return items.filter((item, index, all) => {
    const key = item.url || item.posterUrl;
    return key && all.findIndex((candidate) => (candidate.url || candidate.posterUrl) === key) === index;
  });
}

function tweetImageMediaKey(url) {
  return (url || "").match(/pbs\.twimg\.com\/media\/([^.?/:]+)/)?.[1] || "";
}

function mergeAuthor(primary = {}, fallback = {}) {
  return {
    displayName: primary.displayName || fallback.displayName || "",
    username: primary.username || fallback.username || "",
    avatarUrl: primary.avatarUrl || fallback.avatarUrl || ""
  };
}

function isInsideExcludedNode(node, excludedNodes = []) {
  return excludedNodes.some((excludedNode) => excludedNode && excludedNode !== node && excludedNode.contains(node));
}

  // --- 03-network-capture.js ---
function cacheVideoVariants(mediaId, variants) {
  if (!mediaId || !Array.isArray(variants)) return;
  const mp4s = playableVideoVariants(variants);

  if (mp4s.length > 0) {
    VIDEO_VARIANT_CACHE.set(mediaId, mp4s);
    trimCache(VIDEO_VARIANT_CACHE);
  }
}

function looksLikeTweetResult(node) {
  const legacy = node.legacy || node;
  const media = legacy.extended_entities?.media || legacy.entities?.media || [];
  const userId = legacy.user_id_str || legacy.user_id || node.user_id_str || "";
  return Boolean(
    (node.rest_id || node.id_str) &&
    (legacy.full_text || legacy.text || node.text || media.length > 0) &&
    (node.core?.user_results?.result || node.user || node.author || userId)
  );
}

function looksLikeUserResult(node) {
  return Boolean((node.rest_id || node.id_str) && (node.legacy?.screen_name || node.screen_name || node.username));
}

function cacheUserResult(node) {
  const legacy = node.legacy || node;
  const id = String(node.rest_id || node.id_str || legacy.id_str || "");
  const user = {
    displayName: legacy.name || "",
    username: legacy.screen_name || legacy.username || "",
    avatarUrl: highResolutionProfileImageUrl(legacy.profile_image_url_https || legacy.profile_image_url || "")
  };

  if (id) {
    USER_CACHE.set(id, user);
    trimCache(USER_CACHE);
  }
  if (user.username) {
    USER_CACHE.set(user.username, user);
    trimCache(USER_CACHE);
  }
}

function mediaFromLegacyTweet(legacy) {
  const media = legacy.extended_entities?.media || legacy.entities?.media || [];
  return uniqueMedia(media.flatMap((item) => {
    if (item.type === "photo") {
      return [{ type: "image", url: item.media_url_https || item.media_url || "", alt: item.ext_alt_text || "" }];
    }

    if (item.video_info?.variants) {
      const variants = playableVideoVariants(item.video_info.variants);
      const bestVideoUrl = variants[0]?.url || "";

      return [{
        type: "video",
        url: bestVideoUrl,
        posterUrl: item.media_url_https || item.media_url || "",
        variants,
        alt: item.ext_alt_text || ""
      }];
    }

    return [];
  }));
}

function noteTweetText(node) {
  const note = node.note_tweet?.note_tweet_results?.result;
  let value = String(note?.text || "");
  for (const { url, expanded_url: expandedUrl } of note?.entity_set?.urls || []) {
    if (url && expandedUrl) value = value.split(url).join(expandedUrl);
  }
  return decodeHtmlEntities(value);
}

// The text X sends names a post's media by t.co links the page never shows.
function legacyTweetText(node) {
  const legacy = node.legacy || node;
  let value = String(legacy.full_text || legacy.text || node.text || "");
  for (const { url } of legacy.extended_entities?.media || legacy.entities?.media || []) {
    if (url) value = value.split(url).join("");
  }
  return decodeHtmlEntities(value).replace(/[ \t]+$/gm, "").trim();
}

function cacheTweetResult(node) {
  const legacy = node.legacy || node;
  const userResult = node.core?.user_results?.result;
  const userId = legacy.user_id_str || legacy.user_id || node.user_id_str || "";
  const cachedUser = userId ? USER_CACHE.get(String(userId)) : null;
  const userLegacy = userResult?.legacy || node.user || node.author || cachedUser || {};
  const username = userLegacy.screen_name || userLegacy.username || "";
  const id = String(node.rest_id || node.id_str || legacy.id_str || "");
  if (!id) return;

  const fullText = noteTweetText(node) || TWEET_CACHE.get(id)?.fullText || "";
  TWEET_CACHE.set(id, {
    url: username ? `https://x.com/${username}/status/${id}` : `https://x.com/i/status/${id}`,
    author: {
      displayName: userLegacy.name || "",
      username,
      avatarUrl: highResolutionProfileImageUrl(userLegacy.profile_image_url_https || userLegacy.profile_image_url || "")
    },
    text: fullText || legacyTweetText(node),
    fullText,
    media: mediaFromLegacyTweet(legacy),
    createdAt: legacy.created_at || ""
  });
  trimCache(TWEET_CACHE);
}

function scanForVideoVariants(value) {
  const seen = new WeakSet();

  function visit(node) {
    if (!node || typeof node !== "object") return;
    if (seen.has(node)) return;
    seen.add(node);

    const mediaId = node.id_str || node.media_key || node.id;
    if (looksLikeTweetResult(node)) {
      cacheTweetResult(node);
    }
    if (looksLikeUserResult(node)) {
      cacheUserResult(node);
    }
    if (node.video_info?.variants) {
      cacheVideoVariants(String(mediaId || ""), node.video_info.variants);
    }
    if (node.video?.variants && node.video?.poster) {
      cacheVideoVariants(posterMediaId(node.video.poster) || String(mediaId || ""), node.video.variants);
    }
    if (node.media_url_https && node.video_info?.variants) {
      cacheVideoVariants(posterMediaId(node.media_url_https) || String(mediaId || ""), node.video_info.variants);
    }

    if (Array.isArray(node)) {
      node.forEach(visit);
      return;
    }

    Object.values(node).forEach(visit);
  }

  visit(value);
}

function shouldCaptureApiUrl(url) {
  return /\/graphql\/|\/i\/api\/graphql\/|TweetDetail|UserTweets|HomeTimeline|SearchTimeline/i.test(url);
}

function installNetworkCapture() {
  // Firefox runs the script in an Xray sandbox whose functions the page cannot always call, so a replaced fetch could
  // break X's own requests. Capture stays off there, and the cut-off notice covers long posts.
  if (typeof exportFunction === "function") return;

  // Managers run this script in a sandbox, so X's own requests only pass through the page's window.
  const pageWindow = typeof unsafeWindow === "undefined" ? window : unsafeWindow;
  const originalFetch = pageWindow.fetch;
  if (typeof originalFetch === "function") {
    pageWindow.fetch = async function (...args) {
      const response = await originalFetch.apply(pageWindow, args);
      try {
        const url = String(args[0]?.url || args[0] || "");
        if (shouldCaptureApiUrl(url)) {
          response.clone().json().then(scanForVideoVariants).catch(() => {});
        }
      } catch {}
      return response;
    };
  }

  const xhrPrototype = pageWindow.XMLHttpRequest.prototype;
  const originalOpen = xhrPrototype.open;
  const originalSend = xhrPrototype.send;
  const requestUrls = new WeakMap();
  xhrPrototype.open = function (method, url, ...rest) {
    requestUrls.set(this, String(url || ""));
    return originalOpen.call(this, method, url, ...rest);
  };
  xhrPrototype.send = function (...args) {
    this.addEventListener("load", () => {
      if (!shouldCaptureApiUrl(requestUrls.get(this) || "")) return;
      try {
        scanForVideoVariants(JSON.parse(this.responseText));
      } catch {}
    });
    return originalSend.apply(this, args);
  };
}

  // --- 04-video.js ---
function directVideoUrlsFromDocument() {
  let entries = [];
  try {
    entries = performance.getEntriesByType("resource").map((entry) => entry.name);
  } catch {
    entries = [];
  }

  const sourceUrls = [...document.querySelectorAll("video source[src], video[src]")]
    .map((node) => node.src || node.getAttribute("src") || "");

  return unique([...entries, ...sourceUrls].map(normalizeTweetVideoUrl).filter(isPlayableTweetVideoUrl))
    .sort(compareTweetVideoQuality);
}

function nearestPlayableVideoUrl(video) {
  const candidates = [
    video.currentSrc,
    video.src,
    ...[...video.querySelectorAll("source[src]")].map((source) => source.src || source.getAttribute("src") || "")
  ].map(normalizeTweetVideoUrl).filter(isPlayableTweetVideoUrl).sort(compareTweetVideoQuality);
  if (candidates.length > 0) return candidates[0];

  const poster = video.poster || "";
  const mediaId = posterMediaId(poster);
  const cached = VIDEO_VARIANT_CACHE.get(mediaId);
  if (cached?.length) return cached[0].url;

  const loadedVideos = directVideoUrlsFromDocument();
  const matchingMediaId = mediaId ? loadedVideos.filter((url) => url.includes(`/${mediaId}/`)) : [];
  if (matchingMediaId.length > 0) return matchingMediaId[0];

  const posterName = poster.split("/").pop()?.split("?")[0]?.replace(/\.(jpg|jpeg|png|webp)$/i, "") || "";
  const matchingPoster = loadedVideos.find((url) => posterName && url.includes(posterName));
  if (matchingPoster) return matchingPoster;

  return "";
}

function imageMedia(tweet) {
  return (tweet.media || []).filter((item) => item.type === "image" && item.url && !isTweetVideoThumbnailUrl(item.url));
}

function videoMedia(tweet) {
  return (tweet.media || []).filter((item) => item.type === "video" && (item.url || item.posterUrl));
}

function playableVideoVariantsForMedia(media) {
  const mediaId = posterMediaId(media.posterUrl);
  const cached = mediaId ? (VIDEO_VARIANT_CACHE.get(mediaId) || []) : [];
  const direct = isPlayableTweetVideoUrl(normalizeTweetVideoUrl(media.url || ""))
    ? [{ url: media.url, bitrate: videoQualityScore(media.url), type: "video/mp4" }]
    : [];
  return playableVideoVariants([...(media.variants || []), ...cached, ...direct]);
}

function directPlayableVideoUrls(tweet) {
  return unique(videoMedia(tweet).map((item) => normalizeTweetVideoUrl(item.url)).filter(isPlayableTweetVideoUrl));
}

function bestCachedVideoUrlForTweet(tweet) {
  const mediaIds = videoMedia(tweet).map((item) => posterMediaId(item.posterUrl)).filter(Boolean);
  for (const mediaId of mediaIds) {
    const cached = VIDEO_VARIANT_CACHE.get(mediaId);
    if (cached?.length) return cached[0].url;
  }
  return "";
}

  // --- 05-format-discord.js ---
function tweetAuthorAvatarUrl(tweet) {
  const url = highResolutionProfileImageUrl(tweet.author?.avatarUrl);
  return isHttpsUrl(url) ? url : undefined;
}

function webhookSenderName() {
  return WEBHOOK_SENDER_NAME;
}

// Discord renders markdown in message content and field names, so a name placed there must not pass as a link,
// subtext, or emphasis, and a bare URL in it must not autolink, which escaping its colon prevents. Embed author names
// and titles render no markdown, so they keep the name as written.
function escapeMarkdown(value) {
  return value.replace(/[\\*_~|`[\]()>#:]/g, "\\$&");
}

function authorLabel(post, format = (value) => value) {
  const displayName = format(String(post.author?.displayName || "").trim());
  const username = String(post.author?.username || "").trim();
  const handle = username ? format(`@${username}`) : "";
  if (displayName && handle) return `${displayName} (${handle})`;
  return displayName || handle || "Unknown author";
}

function webhookSenderAvatarUrl() {
  return WEBHOOK_SENDER_AVATAR_URL;
}

// Size variants of one photo share its twimg media ID, so they count as one item.
function mediaUrlIdentity(url) {
  return isTweetImageMediaUrl(url) ? (tweetImageMediaKey(url) || url) : url;
}

function distinctMedia(items, urlOf) {
  const seen = new Set();
  return items.filter((item) => {
    const url = urlOf(item);
    const identity = mediaUrlIdentity(url);
    if (!url || seen.has(identity)) return false;
    seen.add(identity);
    return true;
  });
}

function tweetHasEmbedImageMedia(tweet) {
  return imageMedia(tweet).length > 0;
}

function needsMediaPostPrefix(rootTweet, shareOptions = {}) {
  const { includeQuote = true } = shareOptions;
  if (!includeQuote || !hasQuoteTweet(rootTweet)) return false;
  return tweetHasEmbedImageMedia(rootTweet) && tweetHasEmbedImageMedia(rootTweet.quote);
}

function mediaCaption(kind, postTweet, index, shareOptions = {}, rootTweet = postTweet) {
  const label = kind === "video" ? `Video ${index + 1}` : `Image ${index + 1}`;
  if (!needsMediaPostPrefix(rootTweet, shareOptions)) return label;
  return `${authorLabel(postTweet, escapeMarkdown)} · ${label}`;
}

function videoCaption(postTweet, index, shareOptions = {}, rootTweet = postTweet) {
  const includeQuote = shareOptions.includeQuote !== false;
  const label = `Video ${index + 1}`;
  if (!includeQuote || !hasQuoteTweet(rootTweet)) return label;
  const bothPostsHaveVideo = directPlayableVideoUrls(rootTweet).length > 0 && directPlayableVideoUrls(rootTweet.quote).length > 0;
  return bothPostsHaveVideo || needsMediaPostPrefix(rootTweet, shareOptions) ? `${authorLabel(postTweet, escapeMarkdown)} · ${label}` : label;
}

function mediaLinks(tweet, shareOptions = {}) {
  const videos = directPlayableVideoUrls(tweet).map((url, index) => ({
    kind: "video",
    label: videoCaption(tweet, index, shareOptions),
    url
  }));
  const images = imageMedia(tweet).map((item, index) => ({
    kind: "image",
    label: mediaCaption("image", tweet, index, shareOptions),
    url: item.url
  }));

  return distinctMedia([...videos, ...images], (item) => item.url);
}

function collectMediaAttachmentUrls(tweet, shareOptions = {}) {
  const { includeQuote = true } = shareOptions;
  const posts = [tweet];
  if (includeQuote && hasQuoteTweet(tweet)) posts.push(tweet.quote);
  const urls = [];

  for (const post of posts) {
    for (const item of post.media || []) {
      if (item.type === "video") {
        const url = normalizeTweetVideoUrl(item.url);
        if (isPlayableTweetVideoUrl(url)) urls.push(url);
      } else if (item.type === "image" && isTweetImageMediaUrl(item.url) && !isTweetVideoThumbnailUrl(item.url)) {
        urls.push(item.url);
      }
    }
  }

  return distinctMedia(urls, (url) => url);
}

function isHttpsUrl(url) {
  return /^https:\/\//i.test(String(url || ""));
}

function isValidEmbedImageUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.protocol === "https:" && parsed.hostname === "pbs.twimg.com";
  } catch {
    return false;
  }
}

function embedAuthorBlock(tweet, name, url) {
  const block = { name: truncate(name, DISCORD_EMBED_LIMITS.authorName) };
  const iconUrl = tweetAuthorAvatarUrl(tweet);
  if (iconUrl) block.icon_url = iconUrl;
  if (url) block.url = url;
  return block;
}

function countEmbedChars(embed) {
  let total = 0;
  if (embed.title) total += embed.title.length;
  if (embed.description) total += embed.description.length;
  if (embed.footer?.text) total += embed.footer.text.length;
  if (embed.author?.name) total += embed.author.name.length;
  for (const field of embed.fields || []) {
    total += (field.name || "").length + (field.value || "").length;
  }
  return total;
}

function pruneEmbed(embed) {
  const next = { ...embed };
  for (const key of Object.keys(next)) {
    if (next[key] === undefined || next[key] === null || next[key] === "") delete next[key];
  }
  if (next.fields?.length === 0) delete next.fields;
  return next;
}

function formatQuoteFieldValue(text) {
  const trimmed = String(text || "").trim();
  return trimmed ? trimmed.split("\n").map((line) => `> ${line}`).join("\n") : "";
}

// Null when the quote does not fit one field whole, or has only media to show; the caller gives it a card instead, so
// none of it is lost and its media stays labelled as the quote's.
function buildInlineQuoteFields(quote) {
  const link = quote.url ? `[View quoted post](${quote.url})` : "";
  const value = [formatQuoteFieldValue(quote.text), link].filter(Boolean).join("\n");
  if (!value || value.length > DISCORD_EMBED_LIMITS.fieldValue) return null;

  return [{
    name: truncate(`Quoting ${authorLabel(quote, escapeMarkdown)}`, DISCORD_EMBED_LIMITS.fieldName),
    value,
    inline: false
  }];
}

function shareContentLine(tweet) {
  return tweet.url ? truncate(`-# [Open on X](${tweet.url})`, DISCORD_LIMITS.content) : undefined;
}

function cardPhotoUrls(post, alreadyShown = []) {
  const seen = new Set(alreadyShown.map(mediaUrlIdentity));
  const urls = [];
  for (const { url } of imageMedia(post)) {
    const identity = mediaUrlIdentity(url);
    if (!isValidEmbedImageUrl(url) || seen.has(identity)) continue;
    seen.add(identity);
    urls.push(url);
  }
  return urls;
}

const GRID_PHOTOS = 4;

// Discord merges the embeds of a message that share a url into one grid of up to four images, so every grid in a
// share needs a url of its own. A tag turns one url into another that opens the same post.
function gridUrl(base, tag) {
  return base ? `${base}${base.includes("#") ? "-" : "#"}${tag}` : "";
}

function postCard(post, kind, { images, fields = [], url }) {
  const isQuote = kind === "quote";
  const label = authorLabel(post);
  const profileUrl = post.author?.username ? `https://x.com/${post.author.username}` : undefined;
  const text = String(post.text || "").trim();
  return {
    color: isQuote ? EMBED_COLOR_QUOTE : EMBED_COLOR_MAIN,
    // A quote card has no other visible link to the quoted post, so its author name opens it.
    author: isQuote ? embedAuthorBlock(post, `Quoting ${label}`, post.url) : embedAuthorBlock(post, label, profileUrl),
    text: text || (images.length || mediaLinks(post).length ? "" : "(No text found)"),
    fields,
    images,
    date: discordEmbedTimestamp(post.createdAt),
    footer: { text: "X" },
    url
  };
}

function shareCards(tweet, shareOptions = {}) {
  const url = tweet.url || "";
  if (shareOptions.includeQuote === false || !hasQuoteTweet(tweet)) return [postCard(tweet, "main", { images: cardPhotoUrls(tweet), url })];

  // Extraction can give the main post a photo that belongs to its quote, so the quote keeps every photo of its own and
  // the main card shows the rest. In one card a quote's photos would read as the main post's, so a quote with photos
  // gets its own, as does a quote whose text would not fit a field whole.
  const quoteImages = cardPhotoUrls(tweet.quote);
  const images = cardPhotoUrls(tweet, quoteImages);
  const fields = quoteImages.length ? null : buildInlineQuoteFields(tweet.quote);
  if (fields) return [postCard(tweet, "main", { images, fields, url })];
  const quoteUrl = tweet.quote.url && tweet.quote.url !== url ? tweet.quote.url : gridUrl(url, "quote");
  return [postCard(tweet, "main", { images, url }), postCard(tweet.quote, "quote", { images: quoteImages, url: quoteUrl })];
}

function cardEmbeds(card) {
  const chunks = splitText(card.text, DISCORD_EMBED_LIMITS.description);
  const descriptions = chunks.length ? chunks : [undefined];
  const last = descriptions.length - 1;
  const [hero, ...gallery] = card.images;
  const textEmbeds = descriptions.map((description, index) =>
    pruneEmbed({
      color: card.color,
      author: index === 0 ? card.author : undefined,
      title: index === 0 ? undefined : truncate(`Continued (${index + 1}/${descriptions.length})`, DISCORD_EMBED_LIMITS.title),
      description,
      url: index === 0 ? card.url : undefined,
      image: index === 0 && hero ? { url: hero } : undefined,
      fields: index === last && card.fields.length ? card.fields : undefined,
      timestamp: index === last ? card.date : undefined,
      footer: index === last ? card.footer : undefined
    })
  );
  const [first, ...rest] = textEmbeds;
  const photoEmbed = (url, grid) => pruneEmbed({ color: card.color, url: grid, image: { url } });
  const firstGrid = gallery.slice(0, GRID_PHOTOS - 1).map((url) => photoEmbed(url, card.url));
  const moreGrids = [];
  for (let start = GRID_PHOTOS - 1; start < gallery.length; start += GRID_PHOTOS) {
    const grid = gridUrl(card.url, moreGrids.length + 2);
    moreGrids.push(gallery.slice(start, start + GRID_PHOTOS).map((url) => photoEmbed(url, grid)));
  }
  const host = [first, ...firstGrid];
  while (moreGrids.length && host.length + moreGrids[0].length <= DISCORD_EMBED_LIMITS.embedsPerMessage) {
    host.push(...moreGrids.shift());
  }
  return [host, ...moreGrids, ...rest.map((embed) => [embed])];
}

function shareMessages(tweet, options) {
  return packEmbedsIntoMessages(shareCards(tweet, options).flatMap(cardEmbeds));
}

// Files upload with the first message, so only the photos it shows, and every video, are worth downloading. A photo
// packed into a later message links its source instead.
function uploadCandidateUrls(tweet, options = {}) {
  const [first] = shareMessages(tweet, options);
  const shown = new Set(first.map((embed) => embed.image?.url).filter(Boolean).map(mediaUrlIdentity));
  return collectMediaAttachmentUrls(tweet, options).filter((url) => isPlayableTweetVideoUrl(url) || shown.has(mediaUrlIdentity(url)));
}

function assignUploads(messages, attachments) {
  const fileFor = (url) => url && attachments.find((file) => mediaUrlIdentity(file.sourceUrl) === mediaUrlIdentity(url));
  const [first, ...later] = messages;
  const firstWithUploads = first.map((embed) => {
    const file = fileFor(embed.image?.url);
    return file ? { ...embed, image: { url: `attachment://${file.filename}` } } : embed;
  });
  return { messages: [firstWithUploads, ...later], files: attachments.map((file) => file.filename) };
}

// Same-url embeds only merge within one message, so each group of embeds moves to the next message whole.
function packEmbedsIntoMessages(groups) {
  const messages = [];
  let current = [];
  let currentChars = 0;

  for (const group of groups) {
    const groupChars = group.reduce((sum, embed) => sum + countEmbedChars(embed), 0);
    const fitsSlots = current.length + group.length <= DISCORD_EMBED_LIMITS.embedsPerMessage;
    const fitsChars = currentChars + groupChars <= DISCORD_EMBED_LIMITS.totalEmbedChars;

    if (current.length && !(fitsSlots && fitsChars)) {
      messages.push(current);
      current = [];
      currentChars = 0;
    }

    current.push(...group);
    currentChars += groupChars;
  }

  if (current.length) messages.push(current);
  return messages;
}

function collectShareVideoEntries(tweet, shareOptions = {}) {
  const { includeQuote = true } = shareOptions;
  const entries = [];

  directPlayableVideoUrls(tweet).forEach((url, index) => {
    entries.push({
      url,
      caption: videoCaption(tweet, index, shareOptions, tweet)
    });
  });

  if (includeQuote && hasQuoteTweet(tweet)) {
    directPlayableVideoUrls(tweet.quote).forEach((url, index) => {
      entries.push({
        url,
        caption: videoCaption(tweet.quote, index, shareOptions, tweet)
      });
    });
  }

  return entries;
}

function buildWebhookPayload(embeds, tweet, options = {}) {
  const payload = {
    username: webhookSenderName(),
    avatar_url: webhookSenderAvatarUrl(),
    allowed_mentions: { parse: [] }
  };
  if (embeds.length) payload.embeds = embeds;
  if (options.content) payload.content = options.content;
  if (options.messageLabel) payload._messageLabel = options.messageLabel;
  if (options.files?.length) payload._files = options.files;
  return payload;
}

function buildVideoFollowUpContent(entries) {
  if (!entries.length) return undefined;
  if (entries.length === 1) return truncate(entries[0].url, DISCORD_LIMITS.content);

  const blocks = entries.map((entry) => `-# ${entry.caption}\n${entry.url}`);
  return truncate(blocks.join("\n"), DISCORD_LIMITS.content);
}

function buildEmbedDiscordPayloads(tweet, options = {}) {
  const allVideoEntries = collectShareVideoEntries(tweet, options);
  const fallbackVideoUrlSet = new Set(options.fallbackVideoUrls ?? allVideoEntries.map((entry) => entry.url));
  const videoEntries = allVideoEntries.filter((entry) => fallbackVideoUrlSet.has(entry.url));
  const packed = shareMessages(tweet, options);
  const { messages: groups, files } = assignUploads(packed, options.attachments || []);

  const messages = groups.map((group, index) =>
    buildWebhookPayload(group, tweet, {
      content: index === 0 ? shareContentLine(tweet) : undefined,
      messageLabel: groups.length > 1 ? `Tweet embeds ${index + 1}/${groups.length}` : undefined,
      files: index === 0 ? files : undefined
    })
  );

  const videoContent = buildVideoFollowUpContent(videoEntries);
  if (videoContent) {
    // Discord unfurls MP4 links in content, but not when custom embeds are on the same message.
    messages.push(
      buildWebhookPayload([], tweet, {
        content: videoContent,
        messageLabel: "Videos"
      })
    );
  }
  return messages;
}

function formatMediaLinkPlain(item) {
  if (MEDIA_LINK_STYLE === "masked") {
    return `[${item.label}](${item.url})`;
  }

  return `${item.label}: ${item.url}`;
}

function buildCompactPlainBody(tweet, options = {}) {
  const { includeQuote = true } = options;
  const lines = [authorLabel(tweet, escapeMarkdown)];

  if (tweet.text) lines.push(tweet.text);
  for (const item of mediaLinks(tweet, options)) lines.push(formatMediaLinkPlain(item));
  if (tweet.url) lines.push(tweet.url);

  if (includeQuote && hasQuoteTweet(tweet)) {
    lines.push("");
    lines.push(`↳ ${authorLabel(tweet.quote, escapeMarkdown)}`);
    if (tweet.quote.text) lines.push(tweet.quote.text);
    for (const item of mediaLinks(tweet.quote)) lines.push(formatMediaLinkPlain(item));
    if (tweet.quote.url) lines.push(tweet.quote.url);
  }

  return lines.filter((line, index, all) => line !== "" || (index > 0 && all[index - 1] !== "")).join("\n");
}

function buildPlainFallbackPayloads(tweet, options = {}) {
  const body = buildCompactPlainBody(tweet, options);
  const chunks = splitText(body, MESSAGE_CHUNK_LIMIT);
  const parts = chunks.length ? chunks : [body || authorLabel(tweet, escapeMarkdown)];
  const files = (options.attachments || []).map((file) => file.filename);

  return parts.map((content, index) => ({
    username: webhookSenderName(),
    avatar_url: webhookSenderAvatarUrl(),
    content: truncate(content, DISCORD_LIMITS.content),
    allowed_mentions: { parse: [] },
    ...(index === 0 && files.length ? { _files: files } : {})
  }));
}

function hasQuoteCandidate(tweet) {
  if (!tweet?.quote?.url) return false;
  return tweetIdFromUrl(tweet.quote.url) && tweetIdFromUrl(tweet.quote.url) !== tweetIdFromUrl(tweet.url);
}

function hasQuoteTweet(tweet) {
  const quote = tweet?.quote;
  if (!quote) return false;
  return Boolean(hasQuoteCandidate(tweet) || quote.text || mediaLinks(quote).length > 0);
}

function buildDiscordPayloads(tweet, options = {}) {
  try {
    const embedPayloads = buildEmbedDiscordPayloads(tweet, options);
    if (embedPayloads.length) return embedPayloads;
  } catch (error) {
    console.warn("Tweet Discord Share: embed formatting failed, using plain text", error);
  }

  return buildPlainFallbackPayloads(tweet, options);
}

function splitText(text, limit) {
  const value = String(text || "").trim();
  if (!value) return [];
  const chunks = [];
  let remaining = value;

  while (remaining.length > limit) {
    const splitAt = textBreakBefore(remaining, limit);
    chunks.push(remaining.slice(0, splitAt).trim());
    remaining = remaining.slice(splitAt).trim();
  }

  if (remaining) chunks.push(remaining);
  return chunks;
}

// A break in the first half would leave a short chunk, so only breaks past the middle count.
function textBreakBefore(text, limit) {
  const sentenceEnds = [...text.slice(0, limit + 1).matchAll(/[.!?](?=\s)/g)].map((match) => match.index + 1);
  const breaks = [text.lastIndexOf("\n\n", limit), text.lastIndexOf("\n", limit), sentenceEnds.at(-1) ?? -1, text.lastIndexOf(" ", limit)];
  return breaks.find((index) => index >= Math.floor(limit * 0.5)) ?? limit;
}

  // --- 06-syndication.js ---
function syndicationToken(tweetId) {
  return ((Number(tweetId) / 1e15) * Math.PI)
    .toString(36)
    .replace(/(0+|\.)/g, "");
}

async function fetchSyndicationTweet(tweetId) {
  if (!tweetId) return null;
  try {
    const token = syndicationToken(tweetId);
    return await request(
      "GET",
      `https://cdn.syndication.twimg.com/tweet-result?id=${tweetId}&lang=en&token=${token}`
    );
  } catch (error) {
    console.debug("Tweet Discord Share syndication lookup failed", error);
    return null;
  }
}

function bestSyndicationVideoUrl(data) {
  const candidates = [
    ...(data?.video?.variants || []),
    ...(data?.mediaDetails || []).flatMap((media) => media.video_info?.variants || [])
  ];

  return bestPlayableVideoVariantUrl(candidates);
}

function syndicationPosterUrl(data) {
  return data?.video?.poster || data?.mediaDetails?.find((media) => media.media_url_https)?.media_url_https || "";
}

function syndicationMediaEntityUrls(data) {
  const mediaEntities = Array.isArray(data?.entities?.media) ? data.entities.media : [];
  return unique(mediaEntities.map((entity) => entity.url).filter(Boolean));
}

function visibleSyndicationText(data) {
  let value = String(data?.text || "");
  for (const mediaUrl of syndicationMediaEntityUrls(data)) {
    value = value.split(mediaUrl).join("");
  }
  return value.replace(/[ \t]+$/gm, "").trim();
}

function mediaFromSyndication(data) {
  if (!data) return [];

  const photos = (data.photos || []).map((photo) => ({
    type: "image",
    url: highResolutionTweetImageUrl(photo.url || photo.media_url_https || ""),
    alt: photo.alt_text || ""
  }));
  const details = (data.mediaDetails || []).flatMap((media) => {
    if (media.type === "photo" && media.media_url_https) {
      return [{
        type: "image",
        url: highResolutionTweetImageUrl(media.media_url_https),
        alt: media.ext_alt_text || ""
      }];
    }

    if ((media.type === "video" || media.type === "animated_gif") && media.video_info?.variants) {
      const variants = playableVideoVariants(media.video_info.variants);
      const videoUrl = variants[0]?.url || "";
      const posterUrl = media.media_url_https || "";
      return videoUrl || posterUrl
        ? [{ type: "video", url: videoUrl, posterUrl, variants, alt: media.ext_alt_text || "" }]
        : [];
    }

    return [];
  });
  const topVideoVariants = playableVideoVariants(data.video?.variants || []);
  const topVideoUrl = topVideoVariants[0]?.url || "";
  const topVideo = topVideoUrl || data.video?.poster
    ? [{ type: "video", url: topVideoUrl, posterUrl: data.video?.poster || "", variants: topVideoVariants, alt: "" }]
    : [];

  return uniqueMedia([...photos, ...details, ...topVideo]);
}

function sameTweetImage(left, right) {
  const leftKey = tweetImageMediaKey(left.url);
  return leftKey && leftKey === tweetImageMediaKey(right.url);
}

function sameTweetVideo(left, right) {
  const leftPoster = posterMediaId(left.posterUrl);
  if (leftPoster && leftPoster === posterMediaId(right.posterUrl)) return true;
  const leftUrl = normalizeTweetVideoUrl(left.url || "");
  return leftUrl && leftUrl === normalizeTweetVideoUrl(right.url || "");
}

function mergeTweetMedia(primary = [], fallback = [], options = {}) {
  const media = [...(primary || []), ...(fallback || [])];
  const images = [];
  const videos = [];

  for (const item of media) {
    if (item.type === "image") {
      const normalized = { ...item, url: highResolutionTweetImageUrl(item.url) };
      const existingIndex = images.findIndex((candidate) => sameTweetImage(candidate, normalized));
      if (existingIndex >= 0) {
        const existing = images[existingIndex];
        images[existingIndex] = {
          ...normalized,
          url: existing.url || normalized.url,
          alt: existing.alt || normalized.alt || ""
        };
      } else {
        images.push(normalized);
      }
      continue;
    }

    if (item.type === "video") {
      const normalized = {
        ...item,
        url: normalizeTweetVideoUrl(item.url || ""),
        variants: playableVideoVariants(item.variants || [])
      };
      const existingIndex = videos.findIndex((candidate) => sameTweetVideo(candidate, normalized));
      if (existingIndex >= 0) {
        const existing = videos[existingIndex];
        videos[existingIndex] = {
          ...existing,
          ...normalized,
          url: isPlayableTweetVideoUrl(normalized.url) ? normalized.url : existing.url,
          posterUrl: normalized.posterUrl || existing.posterUrl || "",
          variants: playableVideoVariants([...(existing.variants || []), ...(normalized.variants || [])]),
          alt: normalized.alt || existing.alt || ""
        };
      } else {
        videos.push(normalized);
      }
    }
  }

  const preferredVideoUrl = normalizeTweetVideoUrl(options.cachedVideoUrl || options.videoUrl || "");
  if (preferredVideoUrl) {
    const target = videos.find((item) => !isPlayableTweetVideoUrl(item.url)) || videos[0];
    if (target) {
      target.url = preferredVideoUrl;
      target.posterUrl = target.posterUrl || options.posterUrl || "";
    } else {
      videos.push({ type: "video", url: preferredVideoUrl, posterUrl: options.posterUrl || "", alt: "" });
    }
  }

  return uniqueMedia([...images, ...videos]);
}

function tweetFromSyndication(data, fallback = {}) {
  if (!data) return fallback;

  return {
    ...fallback,
    url: fallback.url || (data.id_str ? `https://x.com/${data.user?.screen_name || "i"}/status/${data.id_str}` : ""),
    author: {
      displayName: data.user?.name || fallback.author?.displayName || "",
      username: data.user?.screen_name || fallback.author?.username || "",
      avatarUrl: highResolutionProfileImageUrl(data.user?.profile_image_url_https || fallback.author?.avatarUrl || "")
    },
    text: fallback.text || visibleSyndicationText(data),
    createdAt: data.created_at || fallback.createdAt || "",
    media: mergeTweetMedia(mediaFromSyndication(data), fallback.media || []),
    quote: fallback.quote
  };
}

// X's quote box usually has no link of its own, so the parent's syndication result supplies the address.
function fillQuoteUrl(quote, quotedTweet) {
  if (!quote || quote.url || !quotedTweet?.id_str) return;
  const username = String(quotedTweet.user?.screen_name || "");
  const shownUsername = String(quote.author?.username || "");
  if (shownUsername && shownUsername.toLowerCase() !== username.toLowerCase()) return;
  quote.url = `https://x.com/${username || "i"}/status/${quotedTweet.id_str}`;
}

function noteTextCutOff(post) {
  if (!post?.textCutOff) return;
  const text = String(post.text || "").trimEnd();
  post.text = `${text.endsWith("…") ? text : `${text}…`}\n\n${TEXT_CUT_OFF_NOTE}`;
}

async function enrichTweetMedia(tweet) {
  tweet = await enrichPost(tweet);
  noteTextCutOff(tweet);
  noteTextCutOff(tweet.quote);
  return tweet;
}

async function enrichPost(tweet) {
  const tweetId = tweetIdFromUrl(tweet.url);
  const data = await fetchSyndicationTweet(tweetId);
  const cachedTweet = tweetId ? TWEET_CACHE.get(tweetId) : null;
  tweet = tweetFromSyndication(data, tweet);
  if (cachedTweet) {
    tweet.url = tweet.url || cachedTweet.url || "";
    tweet.author = mergeAuthor(tweet.author, cachedTweet.author);
    tweet.text = tweet.text || cachedTweet.text || "";
    tweet.createdAt = tweet.createdAt || cachedTweet.createdAt || "";
    tweet.media = mergeTweetMedia(tweet.media || [], cachedTweet.media || []);
  }
  if (cachedTweet?.fullText) {
    tweet.text = cachedTweet.fullText;
    tweet.textCutOff = false;
  }
  const videoUrl = normalizeTweetVideoUrl(bestSyndicationVideoUrl(data));
  const posterUrl = syndicationPosterUrl(data);
  const cachedVideoUrl = bestCachedVideoUrlForTweet(tweet);
  tweet.media = mergeTweetMedia(data ? mediaFromSyndication(data) : [], tweet.media || [], {
    cachedVideoUrl,
    videoUrl,
    posterUrl
  });

  fillQuoteUrl(tweet.quote, data?.quoted_tweet);

  if (hasQuoteCandidate(tweet)) {
    tweet.quote = await enrichPost(tweet.quote);
  }

  if (!hasQuoteTweet(tweet)) {
    tweet.quote = null;
  }

  return tweet;
}

  // --- 07-extract-dom.js ---
function tweetUrlFromArticle(article) {
  const links = [...article.querySelectorAll('a[href*="/status/"]')];
  const statusLinks = links.filter((link) => /\/[^/]+\/status\/\d+/.test(link.getAttribute("href") || ""));
  const pageTweetId = tweetIdFromUrl(location.href);
  const statusLink = statusLinks.find((link) => link.querySelector?.("time"))
    || statusLinks.find((link) => pageTweetId && tweetIdFromUrl(link.href) === pageTweetId)
    || statusLinks[0];
  return statusLink ? normalizeTweetUrl(statusLink.href) : normalizeTweetUrl(location.href);
}

function statusLinksFromArticle(article) {
  const selfHref = article.getAttribute?.("href") || "";
  return [selfHref, ...[...article.querySelectorAll('a[href*="/status/"]')].map((link) => link.href)]
    .filter(Boolean)
    .map((href) => normalizeTweetUrl(href))
    .filter((url, index, all) => /\/status\/\d+/.test(url) && all.indexOf(url) === index);
}

// X draws emoji as <img alt="📸">, which text reads would drop.
function restoreEmojiImages(clone) {
  for (const img of clone.querySelectorAll('img[alt]')) {
    img.replaceWith(img.getAttribute("alt"));
  }
  return clone;
}

function textWithEmoji(node) {
  return node ? restoreEmojiImages(node.cloneNode(true)).textContent.trim() : "";
}

function extractAuthor(article) {
  const userNameBlock = article.querySelector('[data-testid="User-Name"]');
  const avatar = article.querySelector('[data-testid^="UserAvatar-Container"] img, img[src*="profile_images"]');
  const usernameText = [...(userNameBlock || article).querySelectorAll("span")]
    .map((span) => span.textContent?.trim() || "")
    .find((value) => /^@[\w_]+$/.test(value)) || "";
  const profileLink = [...(userNameBlock || article).querySelectorAll('a[href^="/"]')]
    .map((link) => link.getAttribute("href") || "")
    .find((href) => /^\/[^/]+$/.test(href));
  const username = usernameText.slice(1) || profileLink?.slice(1) || "";
  const displayName = textWithEmoji((userNameBlock || article).querySelector('a[href^="/"] div[dir="ltr"] span'))
    || [...(userNameBlock || article).querySelectorAll("span")]
      .map(textWithEmoji)
      .find((value) => value && value !== usernameText && !/^@/.test(value)) || "";

  return {
    displayName,
    username,
    avatarUrl: highResolutionProfileImageUrl(avatar?.src || "")
  };
}

function normalizeTweetBodyText(value) {
  return String(value || "")
    // X often splits "https://" into its own span; innerText inserts a newline.
    .replace(/(https?:\/\/)\s*\n\s*/gi, "$1")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function readTweetTextNode(node) {
  if (typeof node.cloneNode === "function") {
    const clone = restoreEmojiImages(node.cloneNode(true));
    for (const anchor of clone.querySelectorAll("a")) {
      const compact = String(anchor.textContent || "").replace(/\s+/g, "");
      if (/^https?:\/\//i.test(compact) || /^[\w.-]+\.[a-z]{2,}\//i.test(compact)) {
        anchor.replaceWith(compact);
      }
    }
    return normalizeTweetBodyText(clone.innerText || clone.textContent || "");
  }

  return normalizeTweetBodyText(node.innerText || node.textContent || "");
}

function extractText(article, excludedNodes = []) {
  return [...article.querySelectorAll('[data-testid="tweetText"]')]
    .filter((node) => !isInsideExcludedNode(node, excludedNodes))
    .map(readTweetTextNode)
    .filter(Boolean)
    .join("\n\n");
}

function textIsCutOff(article, excludedNodes = []) {
  return [...article.querySelectorAll('[data-testid="tweet-text-show-more-link"]')]
    .some((node) => !isInsideExcludedNode(node, excludedNodes));
}

function imageNodePixelSize(img) {
  return Math.max(
    Number(img.naturalWidth || 0),
    Number(img.naturalHeight || 0),
    Number(img.width || 0),
    Number(img.height || 0),
    Number(img.clientWidth || 0),
    Number(img.clientHeight || 0)
  );
}

function isLikelyTweetMediaImageNode(img) {
  if (!isTweetImageMediaUrl(img.src) || isTweetVideoThumbnailUrl(img.src)) return false;
  const size = imageNodePixelSize(img);
  return size === 0 || size >= 96;
}

function extractMedia(article, excludedNodes = []) {
  const photoImages = [...article.querySelectorAll('[data-testid="tweetPhoto"] img')]
    .filter((img) => !isInsideExcludedNode(img, excludedNodes))
    .filter((img) => isTweetImageMediaUrl(img.src) && !isTweetVideoThumbnailUrl(img.src));
  const fallbackImages = [...article.querySelectorAll('img[src*="pbs.twimg.com/media/"]')]
    .filter((img) => !isInsideExcludedNode(img, excludedNodes))
    .filter((img) => !img.closest?.('[data-testid="tweetPhoto"]'))
    .filter(isLikelyTweetMediaImageNode);
  const images = [...photoImages, ...fallbackImages]
    .map((img) => ({ type: "image", url: highResolutionTweetImageUrl(img.src), alt: img.alt || "" }));
  const videos = [...article.querySelectorAll("video")]
    .filter((video) => !isInsideExcludedNode(video, excludedNodes))
    .map((video) => ({
      type: "video",
      url: nearestPlayableVideoUrl(video),
      posterUrl: isTweetVideoPosterUrl(video.poster) ? video.poster : "",
      alt: ""
    }));

  return uniqueMedia([...images, ...videos]);
}

function extractTimestamp(article) {
  return article.querySelector("time")?.getAttribute("datetime") || "";
}

function quoteCandidateHasContent(node) {
  return [
    '[data-testid="tweetText"]',
    '[data-testid="tweetPhoto"] img',
    'img[src*="pbs.twimg.com/media/"]',
    "video"
  ].some((selector) => node.querySelector?.(selector));
}

function outermostQuoteCandidate(candidates) {
  return candidates.find((candidate) =>
    !candidates.some((other) =>
      other !== candidate && typeof other.contains === "function" && other.contains(candidate)
    )
  );
}

function extractQuote(article) {
  const mainUrl = tweetUrlFromArticle(article);
  const mainTweetId = tweetIdFromUrl(mainUrl);
  const statusLinks = statusLinksFromArticle(article);
  const quotedLink = statusLinks.find((href) => href !== mainUrl && tweetIdFromUrl(href) !== mainTweetId);
  const quotedTweetId = tweetIdFromUrl(quotedLink);

  const quoteCandidates = [
    ...article.querySelectorAll('[role="link"]'),
    ...article.querySelectorAll('[data-testid="card.wrapper"]')
  ];
  const linkedQuoteCandidates = quotedTweetId
    ? quoteCandidates.filter((node) =>
      statusLinksFromArticle(node).some((href) => tweetIdFromUrl(href) === quotedTweetId)
    )
    : [];
  const quoteOnlyCandidates = linkedQuoteCandidates.filter((node) =>
    !statusLinksFromArticle(node).some((href) => tweetIdFromUrl(href) === mainTweetId)
  );
  const scopedQuoteCandidates = quoteOnlyCandidates.length ? quoteOnlyCandidates : linkedQuoteCandidates;
  const contentQuoteCandidates = scopedQuoteCandidates.filter(quoteCandidateHasContent);
  // A quote box with no link of its own still carries the quoted author's name, and a media-only one carries no text.
  const quotedContainer = outermostQuoteCandidate(contentQuoteCandidates)
    || outermostQuoteCandidate(scopedQuoteCandidates)
    || quoteCandidates.find((node) => node !== article && node.querySelector('[data-testid="tweetText"]'))
    || quoteCandidates.find((node) => node !== article && node.querySelector('[data-testid="User-Name"]'));

  if (!quotedContainer && !quotedLink) return null;

  const quote = {
    url: quotedLink ? normalizeTweetUrl(quotedLink) : "",
    author: quotedContainer ? extractAuthor(quotedContainer) : { displayName: "", username: "", avatarUrl: "" },
    text: quotedContainer ? extractText(quotedContainer) : "",
    textCutOff: quotedContainer ? textIsCutOff(quotedContainer) : false,
    media: quotedContainer ? extractMedia(quotedContainer) : [],
    createdAt: quotedContainer ? extractTimestamp(quotedContainer) : "",
    container: quotedContainer || null
  };

  const cachedQuote = quote.url ? TWEET_CACHE.get(tweetIdFromUrl(quote.url)) : null;
  if (cachedQuote) {
    quote.url = cachedQuote.url || quote.url;
    quote.author = mergeAuthor(cachedQuote.author, quote.author);
    quote.text = quote.text || cachedQuote.text || "";
    quote.media = mergeTweetMedia(cachedQuote.media || [], quote.media || []);
    quote.createdAt = cachedQuote.createdAt || quote.createdAt;
  }

  if (DEBUG_QUOTE_EXTRACTION) {
    console.group("Tweet Discord Share quote debug");
    console.log("mainUrl", mainUrl);
    console.log("statusLinks", statusLinks);
    console.log("quotedLink", quotedLink);
    console.log("quotedContainer", quotedContainer);
    console.log("cachedQuote", cachedQuote);
    console.log("tweetCache", Object.fromEntries(TWEET_CACHE));
    console.log("userCache", Object.fromEntries(USER_CACHE));
    console.groupEnd();
  }

  if (!quote.url && !quote.text && quote.media.length === 0) return null;
  if (quote.url && quote.url === mainUrl && !quote.text && quote.media.length === 0) return null;

  return quote;
}

function extractTweet(article) {
  const quote = extractQuote(article);
  const excludedMediaNodes = quote?.container ? [quote.container] : [];

  if (quote) {
    delete quote.container;
  }

  return {
    url: tweetUrlFromArticle(article),
    author: extractAuthor(article),
    text: extractText(article, excludedMediaNodes),
    textCutOff: textIsCutOff(article, excludedMediaNodes),
    media: extractMedia(article, excludedMediaNodes),
    createdAt: extractTimestamp(article),
    quote
  };
}

  // --- 08-deliver.js ---
function sanitizeWebhookPayload(payload) {
  const { _messageLabel, _files, ...discordPayload } = payload;
  return discordPayload;
}

function buildWebhookTestPayload() {
  return {
    username: webhookSenderName(),
    avatar_url: webhookSenderAvatarUrl(),
    content: "Tweet Discord Share connected — this channel is ready to receive shares."
  };
}

async function sendWebhookTest(webhookUrl) {
  const url = String(webhookUrl || "").trim();
  if (!isValidWebhookUrl(url)) {
    throw new Error("Enter a valid Discord webhook URL.");
  }
  await request("POST", url, buildWebhookTestPayload());
}

async function shareToDestination(destinationId, tweet, options = {}) {
  const destination = await getDestinationById(destinationId);
  if (!destination?.webhookUrl) {
    throw new Error("That destination is missing a webhook URL.");
  }

  const resolved = await resolveAttachmentsForTweet(tweet, options);
  const attachments = resolved.attachments;
  const fallbackVideoUrls = resolved.skipped
    .map((item) => item.sourceUrl)
    .filter((url) => isPlayableTweetVideoUrl(url));
  const payloads = buildDiscordPayloads(tweet, {
    ...options,
    attachments: attachments.map(({ filename, sourceUrl }) => ({ filename, sourceUrl })),
    fallbackVideoUrls
  });
  const messages = payloads.map((payload) => ({
    payload: sanitizeWebhookPayload(payload),
    files: attachments.filter((attachment) => payload._files?.includes(attachment.filename))
  }));
  const uploadedCount = messages.reduce((count, message) => count + message.files.length, 0);

  if (resolved.skipped.length > 0 && uploadedCount === 0) {
    const skippedSummary = summarizeSkippedMedia(resolved.skipped);
    showToast(`Media not uploaded; ${skippedSummary}.`, "info");
  }

  for (let index = 0; index < messages.length; index += 1) {
    const { payload, files } = messages[index];
    try {
      if (files.length > 0) {
        await requestMultipart(
          destination.webhookUrl,
          payload,
          files.map((attachment, fileIndex) => ({
            name: `files[${fileIndex}]`,
            filename: attachment.filename,
            bytes: attachment.bytes,
            contentType: attachment.contentType
          }))
        );
      } else {
        await request("POST", destination.webhookUrl, payload);
      }
    } catch (error) {
      if (index === 0) throw error;
      throw new Error(
        `Sent ${index} of ${messages.length} Discord messages before delivery failed: ${error.message}`,
        { cause: error }
      );
    }
    if (index < messages.length - 1) {
      await delay(WEBHOOK_SEND_DELAY_MS);
    }
  }

  if (uploadedCount > 0 && resolved.skipped.length > 0) {
    const skippedSummary = summarizeSkippedMedia(resolved.skipped);
    showToast(`Uploaded ${uploadedCount} file${uploadedCount === 1 ? "" : "s"}; ${skippedSummary}.`, "info");
  }
}

  // --- 09-surface.js ---
// Shared UI surface helpers: styles, toasts, and popover positioning.
let activePanel = null;

function appendWhenReady(node) {
  if (document.documentElement) {
    document.documentElement.append(node);
    return;
  }

  document.addEventListener("DOMContentLoaded", () => document.documentElement.append(node), { once: true });
}

function injectStyles() {
  const style = document.createElement("style");
  style.textContent = `
    ${tdsSharedSurfaceCss()}
    ${popoverStylesCss()}
    ${previewStylesCss()}

    .${SHARE_MENU_ITEM_CLASS} {
      cursor: pointer;
    }

    .${AVATAR_CLASS} {
      align-items: center;
      border-radius: 10px;
      color: #fff;
      display: inline-flex;
      flex-shrink: 0;
      font-size: 15px;
      font-weight: 800;
      height: 34px;
      justify-content: center;
      width: 34px;
    }

    .${TOAST_HOST_CLASS} {
      position: fixed;
      inset-inline-end: 16px;
      bottom: 16px;
      z-index: 10001;
      display: flex;
      flex-direction: column-reverse;
      gap: 8px;
      pointer-events: none;
      max-width: min(360px, calc(100vw - 32px));
    }
    .${TOAST_CLASS} {
      animation: tds-toast-in 0.2s ease;
      border-radius: 12px;
      font-size: 15px;
      font-weight: 600;
      line-height: 1.35;
      padding-block: 12px;
      padding-inline: 40px 14px;
      pointer-events: auto;
      position: relative;
    }
    .${TOAST_CLASS}::before {
      border-radius: 999px;
      color: rgb(var(--tds-surface));
      font-size: 12px;
      font-weight: 800;
      height: 18px;
      inset-inline-start: 12px;
      line-height: 18px;
      position: absolute;
      text-align: center;
      top: 13px;
      width: 18px;
    }
    /* The "/ ''" alt text keeps the icon glyph out of what screen readers announce. */
    .${TOAST_CLASS}[data-state="success"]::before {
      background: rgb(var(--tds-success));
      content: "✓";
      content: "✓" / "";
    }
    .${TOAST_CLASS}[data-state="error"]::before {
      background: rgb(var(--tds-danger));
      content: "!";
      content: "!" / "";
    }
    .${TOAST_CLASS}[data-state="info"]::before {
      background: rgb(var(--tds-link));
      content: "…";
      content: "…" / "";
      line-height: 14px;
    }
    @keyframes tds-toast-in {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }
  `;
  appendWhenReady(style);
}

function getToastHost() {
  let host = document.querySelector(`.${TOAST_HOST_CLASS}`);
  if (!host) {
    host = document.createElement("div");
    host.className = TOAST_HOST_CLASS;
    appendWhenReady(host);
  }
  return host;
}

function showToast(message, state = "info") {
  const host = getToastHost();
  const toastEl = document.createElement("div");
  toastEl.className = TOAST_CLASS;
  applyXThemeVars(toastEl);
  toastEl.dataset.state = state;
  toastEl.setAttribute("role", state === "error" ? "alert" : "status");
  toastEl.textContent = message;
  host.append(toastEl);

  window.setTimeout(() => {
    toastEl.style.opacity = "0";
    toastEl.style.transform = "translateY(4px)";
    toastEl.style.transition = "opacity 0.2s ease, transform 0.2s ease";
    window.setTimeout(() => toastEl.remove(), 220);
  }, TOAST_DURATION_MS);
}

function closeXOverlay() {
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", code: "Escape", bubbles: true }));
}

function closeDestinationMenu() {
  activePanel?.close();
}

const PANEL_MARGIN = 8;
const NARROW_VIEWPORT_WIDTH = 500;
const NARROW_VIEWPORT_MEDIA = `(max-width: ${NARROW_VIEWPORT_WIDTH - 0.02}px)`;

function clamp(value, min, max) {
  return Math.max(min, Math.min(value, max));
}

// What the user sees, in the coordinates of getBoundingClientRect and fixed positioning. Pinch zoom shrinks and moves it.
function visibleViewport() {
  const visual = window.visualViewport;
  return visual
    ? new DOMRect(visual.offsetLeft, visual.offsetTop, visual.width, visual.height)
    : new DOMRect(0, 0, window.innerWidth, window.innerHeight);
}

function rectsOverlap(a, b) {
  return a.left <= b.right && b.left <= a.right && a.top <= b.bottom && b.top <= a.bottom;
}

// Rects and sizes are in viewport pixels, and `viewport` is the part of the page the user sees.
// maxHeight caps the panel so only its preview scrolls.
// A sheet spans that width, and its top is that bottom edge. Its CSS lifts it by its own height, so placing it needs no measuring.
function placePanel({ anchorRect, panelSize, viewport }) {
  if (viewport.width < NARROW_VIEWPORT_WIDTH) {
    return { mode: "sheet", top: viewport.bottom, left: viewport.left, width: viewport.width, maxHeight: Math.round(viewport.height * 0.85) };
  }

  const maxHeight = viewport.height - PANEL_MARGIN * 2;
  const height = Math.min(panelSize.height, maxHeight);
  const left = clamp(
    anchorRect.left + anchorRect.width / 2 - panelSize.width / 2,
    viewport.left + PANEL_MARGIN,
    viewport.right - panelSize.width - PANEL_MARGIN
  );
  let mode = "clamped";
  let top = anchorRect.top + anchorRect.height / 2 - height / 2;
  if (panelSize.height <= anchorRect.top - viewport.top - PANEL_MARGIN * 2) {
    mode = "above";
    top = anchorRect.top - PANEL_MARGIN - panelSize.height;
  } else if (panelSize.height <= viewport.bottom - anchorRect.bottom - PANEL_MARGIN * 2) {
    mode = "below";
    top = anchorRect.bottom + PANEL_MARGIN;
  }
  top = clamp(top, viewport.top + PANEL_MARGIN, viewport.bottom - height - PANEL_MARGIN);
  return { mode, top: Math.round(top), left: Math.round(left), maxHeight };
}

// The panel is measured with none of a sheet's styles, which change its width and border.
// Measured at full height, the panel and its preview lose where they were scrolled to, so that is put back.
function positionPopover(panel, anchorRect) {
  const scrolled = [panel, ...panel.children].map((node) => [node, node.scrollTop]);
  panel.style.maxHeight = "";
  panel.style.width = "";
  panel.classList.remove(`${POPOVER_CLASS}--sheet`);
  if (!panel.isConnected) {
    document.body.append(panel);
  }

  const { width, height } = panel.getBoundingClientRect();
  const placement = placePanel({ anchorRect, panelSize: { width, height }, viewport: visibleViewport() });
  panel.classList.toggle(`${POPOVER_CLASS}--sheet`, placement.mode === "sheet");
  panel.style.top = `${placement.top}px`;
  panel.style.left = `${placement.left}px`;
  panel.style.width = placement.width === undefined ? "" : `${placement.width}px`;
  panel.style.maxHeight = `${placement.maxHeight}px`;
  for (const [node, scrollTop] of scrolled) node.scrollTop = scrollTop;
}

// Escape is the panel's only while focus is in it, on its Share button, or nowhere, so Escape elsewhere on X is left alone.
// When X re-renders the post away, the panel keeps the place its Share button last had.
function showPanel(panel, { findAnchor, returnFocus }) {
  closeDestinationMenu();
  let anchorRect = new DOMRect();
  const place = () => {
    anchorRect = findAnchor()?.getBoundingClientRect() ?? anchorRect;
    positionPopover(panel, anchorRect);
  };
  const ownsFocus = (node) => node === document.body || panel.contains(node) || node === findAnchor();
  const onKeyDown = (event) => {
    if (event.key !== "Escape" || event.defaultPrevented || !ownsFocus(document.activeElement)) return;
    close();
    returnFocus();
  };
  const onPointerDown = (event) => {
    if (!panel.contains(event.target) && !findAnchor()?.contains(event.target)) close();
  };
  const listeners = [
    [document, "keydown", onKeyDown, false],
    [document, "pointerdown", onPointerDown, true],
    [window, "resize", place, false],
    [window, "orientationchange", place, false],
    [window.visualViewport, "resize", place, false],
    [window.visualViewport, "scroll", place, false]
  ].filter(([target]) => target);

  function close() {
    for (const [target, type, listener, capture] of listeners) target.removeEventListener(type, listener, capture);
    panel.remove();
    activePanel = null;
  }

  for (const [target, type, listener, capture] of listeners) target.addEventListener(type, listener, capture);
  place();
  panel.focus({ preventScroll: true });
  activePanel = { place, close, ownsFocus, returnFocus };
  return activePanel;
}

// The first character a reader sees, so a flag or a family emoji stays whole.
function firstGrapheme(text) {
  if (!Intl.Segmenter) return [...text][0];
  return new Intl.Segmenter().segment(text)[Symbol.iterator]().next().value?.segment;
}

function createChannelAvatar(destination) {
  const avatar = document.createElement("span");
  avatar.className = AVATAR_CLASS;
  avatar.setAttribute("aria-hidden", "true");
  avatar.textContent = firstGrapheme(destination.label.trim())?.toUpperCase() || "#";
  let hash = 0;
  for (const char of destination.id) hash = (hash * 31 + char.codePointAt(0)) >>> 0;
  avatar.style.background = avatarColor(hash % 360);
  return avatar;
}

