// A filled "#" channel glyph, drawn like X's own filled menu icons.
const CHANNEL_ICON_PATHS = [
  "M9.1 3.5h2l-2.2 17h-2z",
  "M15.1 3.5h2l-2.2 17h-2z",
  "M3.5 8h17v2h-17z",
  "M3.5 14h17v2h-17z"
];

let pendingShareArticle = null;
function articleHasQuotableTweet(article) {
  try {
    return hasQuoteTweet(extractTweet(article));
  } catch {
    return false;
  }
}

async function prepareShareTweet(article) {
  const tweet = await enrichTweetMedia(extractTweet(article));
  if (DEBUG_MEDIA_EXTRACTION) {
    console.group("Tweet Discord Share media debug");
    console.log(tweet);
    console.log("Detected direct video URLs", directVideoUrlsFromDocument());
    console.log("Cached video variants", Object.fromEntries(VIDEO_VARIANT_CACHE));
    console.groupEnd();
  }
  return tweet;
}


async function runShare(article, destinationId, options = {}, preparedTweet = null) {
  showToast(preparedTweet ? "Sending…" : "Preparing…", "info");

  try {
    const tweet = preparedTweet ?? await prepareShareTweet(article);
    await shareToDestination(destinationId, tweet, options);
    const cutOff = tweet.textCutOff || (options.includeQuote !== false && tweet.quote?.textCutOff);
    showToast(`Sent to ${await destinationLabel(destinationId)}${cutOff ? ". Post text was cut off; open it on X for the rest." : ""}`, "success");
  } catch (error) {
    console.error(error);
    showToast(error.message, "error");
  }
}

async function startDiscordShare(article, anchor) {
  const [destinations, preferences] = await Promise.all([getDestinations(), loadPreferences()]);
  if (destinations.length === 0) {
    const findPostShareButton = trackShareButton(article, anchor);
    closeXOverlay();
    openSettingsModal(() => returnFocusToPost(findPostShareButton));
    return;
  }

  const showQuoteOption = articleHasQuotableTweet(article);
  if (destinations.length === 1 && !showQuoteOption && !preferences.alwaysShowPreview) {
    closeXOverlay();
    await runShare(article, destinations[0].id, {
      includeQuote: true,
      preferences
    }, null);
    return;
  }

  closeXOverlay();
  window.setTimeout(
    () => openDestinationMenu(anchor, article, destinations, { showQuoteOption, preferences }),
    50
  );
}

function findShareButton(root) {
  return root.querySelector('[data-testid="share"]')
    || [...root.querySelectorAll("button")].find((button) => /share/i.test(button.getAttribute("aria-label") || ""));
}

// X can re-render a post while the panel or settings are open, which replaces its Share button.
// The finder remembers where on the page the button last was, to tell copies of the post apart.
function trackShareButton(article, anchor) {
  const postUrl = tweetUrlFromArticle(article);
  let lastRect = toPageRect(anchor.getBoundingClientRect());
  return () => {
    const button = anchor.isConnected ? anchor
      : article.isConnected ? findShareButton(article)
        : nearestShareButtonCopy(postUrl, lastRect);
    if (button) lastRect = toPageRect(button.getBoundingClientRect());
    return button;
  };
}

// Scrolling the page moves a rect in the viewport, so another copy of the post can scroll into where Share was.
function toPageRect({ x, y, width, height }) {
  return new DOMRect(x + window.scrollX, y + window.scrollY, width, height);
}

// The same post can be on the page twice, as in a repost. Only a copy where the Share button last was,
// or one in view, can stand in for it, so focusing it never jumps the page.
function nearestShareButtonCopy(postUrl, lastRect) {
  const viewport = toPageRect(visibleViewport());
  const distance = ({ rect }) => Math.hypot(rect.x - lastRect.x, rect.y - lastRect.y);
  return [...document.querySelectorAll("article")]
    .filter((candidate) => !candidate.closest(`.${POPOVER_CLASS}`) && tweetUrlFromArticle(candidate) === postUrl)
    .map(findShareButton)
    .filter(Boolean)
    .map((button) => ({ button, rect: toPageRect(button.getBoundingClientRect()) }))
    .filter(({ rect }) => rectsOverlap(rect, lastRect) || rectsOverlap(rect, viewport))
    .sort((a, b) => distance(a) - distance(b))[0]?.button ?? null;
}

const FOCUSABLE_SELECTOR = 'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])';

// The browser refuses focus to hidden, inert, and disabled controls, so a target counts once focus actually lands.
function focusIfAble(target) {
  if (!target || target.closest('[aria-hidden="true"]')) return false;
  target.focus({ preventScroll: true });
  return document.activeElement === target;
}

// The browser still focuses a control with no size or no opacity, its own or an ancestor's.
function isVisible(control) {
  const { width, height } = control.getBoundingClientRect();
  if (!width || !height) return false;
  for (let node = control; node; node = node.parentElement) {
    if (Number(getComputedStyle(node).opacity) === 0) return false;
  }
  return true;
}

// With the post gone, focus goes to a visible control in view, X's main column first, and as a last resort to main itself.
function focusFallbackControl() {
  const main = document.querySelector("main");
  const controls = [...new Set([...(main?.querySelectorAll(FOCUSABLE_SELECTOR) ?? []), ...document.querySelectorAll(FOCUSABLE_SELECTOR)])];
  const viewport = visibleViewport();
  const inView = controls.filter((control) => rectsOverlap(control.getBoundingClientRect(), viewport));
  if ([...inView, ...controls].some((control) => isVisible(control) && focusIfAble(control)) || !main) return;
  if (!main.hasAttribute("tabindex")) {
    main.tabIndex = -1;
    main.addEventListener("blur", () => main.removeAttribute("tabindex"), { once: true });
  }
  main.focus({ preventScroll: true });
}

function returnFocusToPost(findPostShareButton) {
  if (!focusIfAble(findPostShareButton())) focusFallbackControl();
}

function captureShareArticle(event) {
  const shareButton = event.target.closest('[data-testid="share"], button[aria-label*="Share" i]');
  if (!shareButton) return;
  pendingShareArticle = shareButton.closest("article");
}

function isXShareMenu(node) {
  if (!node || node.getAttribute("role") !== "menu") return false;
  const text = [...node.querySelectorAll('[role="menuitem"]')]
    .map((item) => item.textContent || "")
    .join(" ")
    .toLowerCase();
  return text.includes("copy link")
    || text.includes("share post")
    || text.includes("embed post")
    || text.includes("send via");
}

function getMenuItemLabelSpans(menuItem) {
  return [...menuItem.querySelectorAll("span")].filter((node) => {
    return !node.closest("svg") && node.textContent.trim().length > 0;
  });
}

function findMenuItemLabelElement(item, referenceItem) {
  const itemSpans = getMenuItemLabelSpans(item);
  if (!referenceItem) {
    return itemSpans.find((node) => node.children.length === 0) || itemSpans[0] || null;
  }

  const refSpans = getMenuItemLabelSpans(referenceItem);
  const refLabel = refSpans.find((node) => node.children.length === 0) || refSpans[refSpans.length - 1];
  if (!refLabel) {
    return itemSpans[0] || null;
  }

  const refIndex = refSpans.indexOf(refLabel);
  if (refIndex >= 0 && itemSpans[refIndex]) {
    return itemSpans[refIndex];
  }

  return itemSpans.find((node) => node.children.length === 0) || itemSpans[0] || null;
}

function replaceMenuItemIcon(item) {
  const svg = item.querySelector("svg");
  if (!svg) return;

  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("aria-hidden", "true");
  svg.replaceChildren(...CHANNEL_ICON_PATHS.map((d) => {
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    path.setAttribute("d", d);
    path.setAttribute("fill", "currentColor");
    return path;
  }));
}

function replaceMenuItemText(item, text, referenceItem) {
  const label = findMenuItemLabelElement(item, referenceItem);
  if (label) {
    label.textContent = text;
    return true;
  }

  const walker = document.createTreeWalker(item, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.textContent.trim().length > 1 && !node.parentElement?.closest("svg")) {
      node.textContent = text;
      return true;
    }
  }

  return false;
}

function findShareMenuTemplate(menu) {
  const items = [...menu.querySelectorAll('[role="menuitem"]')].filter((item) => {
    return !item.classList.contains(SHARE_MENU_ITEM_CLASS);
  });

  return items.find((item) => /share post/i.test(item.textContent || ""))
    || items.find((item) => /copy link/i.test(item.textContent || ""))
    || items[0]
    || null;
}

function wireDiscordMenuItem(item) {
  item.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const article = pendingShareArticle;
    if (!article) {
      showToast("Could not find the post. Try opening Share again.", "error");
      return;
    }
    // X removes its menu, and this item with it, so the panel anchors to the post's Share button.
    startDiscordShare(article, findShareButton(article) || item);
  });

  item.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      item.click();
    }
  });
}

function createDiscordMenuItem(template) {
  const item = template ? template.cloneNode(true) : document.createElement("div");
  item.setAttribute("role", "menuitem");
  item.tabIndex = 0;
  item.classList.add(SHARE_MENU_ITEM_CLASS);

  replaceMenuItemText(item, "Share to Discord", template);
  replaceMenuItemIcon(item);

  wireDiscordMenuItem(item);
  return item;
}

function injectDiscordShareMenuItem(menu) {
  if (menu.querySelector(`.${SHARE_MENU_ITEM_CLASS}`)) return;

  const template = findShareMenuTemplate(menu);
  const item = createDiscordMenuItem(template);
  const firstItem = menu.querySelector(`[role="menuitem"]:not(.${SHARE_MENU_ITEM_CLASS})`);

  if (firstItem?.parentElement) {
    firstItem.parentElement.insertBefore(item, firstItem);
    return;
  }

  menu.append(item);
}

function shareMenusNearNode(node) {
  if (!node || node.nodeType !== Node.ELEMENT_NODE) return [];

  const menus = [];
  if (node.matches?.('[role="menu"]')) menus.push(node);
  node.querySelectorAll?.('[role="menu"]').forEach((menu) => menus.push(menu));
  const parentMenu = node.closest?.('[role="menu"]');
  if (parentMenu) menus.push(parentMenu);
  return [...new Set(menus)];
}

function scanShareMenus(root = document) {
  const menus = root === document
    ? [...document.querySelectorAll('[role="menu"]')]
    : shareMenusNearNode(root);

  menus.forEach((menu) => {
    if (isXShareMenu(menu)) {
      injectDiscordShareMenuItem(menu);
    }
  });
}

function removeLegacyDiscordButtons() {
  document.querySelectorAll(".tds-action-slot, .tds-share-button").forEach((node) => node.remove());
}

function installShareMenuIntegration() {
  document.addEventListener("click", captureShareArticle, true);

  const pendingNodes = new Set();
  let scanScheduled = false;
  const flushAddedNodes = () => {
    scanScheduled = false;
    const nodes = [...pendingNodes];
    pendingNodes.clear();
    nodes.forEach((node) => scanShareMenus(node));
  };

  const observer = new MutationObserver((records) => {
    for (const record of records) {
      for (const node of record.addedNodes || []) {
        if (node.nodeType === Node.ELEMENT_NODE) pendingNodes.add(node);
      }
    }
    if (pendingNodes.size > 0 && !scanScheduled) {
      scanScheduled = true;
      queueMicrotask(flushAddedNodes);
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
  scanShareMenus();
}

function startUi() {
  injectStyles();
  installNetworkCapture();
  removeLegacyDiscordButtons();
  installShareMenuIntegration();
}

startUi();

  // --- 10-destinations.js ---
function storageGet(key, defaultValue) {
  return new Promise((resolve) => {
    if (typeof GM !== "undefined" && typeof GM.getValue === "function") {
      GM.getValue(key, defaultValue).then(resolve).catch(() => resolve(defaultValue));
      return;
    }
    if (typeof GM_getValue === "function") {
      try {
        const value = GM_getValue(key, defaultValue);
        if (value && typeof value.then === "function") {
          value.then(resolve).catch(() => resolve(defaultValue));
          return;
        }
        resolve(value ?? defaultValue);
      } catch {
        resolve(defaultValue);
      }
      return;
    }
    resolve(defaultValue);
  });
}

function storageSet(key, value) {
  return new Promise((resolve, reject) => {
    if (typeof GM !== "undefined" && typeof GM.setValue === "function") {
      GM.setValue(key, value).then(resolve).catch(reject);
      return;
    }
    if (typeof GM_setValue === "function") {
      try {
        const result = GM_setValue(key, value);
        if (result && typeof result.then === "function") {
          result.then(resolve).catch(reject);
          return;
        }
        resolve();
      } catch (error) {
        reject(error);
      }
      return;
    }
    reject(new Error("Extension storage is unavailable."));
  });
}

function slugifyId(value) {
  const slug = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || `channel-${Date.now().toString(36)}`;
}

function sanitizeDestination(entry) {
  if (!entry || typeof entry !== "object") return null;
  const id = String(entry.id || "").trim();
  const label = String(entry.label || "").trim();
  const webhookUrl = String(entry.webhookUrl || "").trim();
  if (!id || !label || !webhookUrl) return null;
  if (!WEBHOOK_URL_PATTERN.test(webhookUrl)) return null;
  return { id, label, webhookUrl };
}

function sanitizeDestinations(entries) {
  if (!Array.isArray(entries)) return [];
  return entries.map(sanitizeDestination).filter(Boolean);
}

async function readStoredDestinations() {
  const stored = await storageGet(DESTINATIONS_STORAGE_KEY, null);
  return sanitizeDestinations(stored);
}

async function loadAllDestinations() {
  return readStoredDestinations();
}

async function saveAllDestinations(destinations) {
  const sanitized = sanitizeDestinations(destinations);
  await storageSet(DESTINATIONS_STORAGE_KEY, sanitized);
  return sanitized;
}

async function getDestinations() {
  const destinations = await loadAllDestinations();
  return destinations.map(({ id, label }) => ({ id, label }));
}

async function getDestinationById(destinationId) {
  const destinations = await loadAllDestinations();
  return destinations.find((item) => item.id === destinationId) || null;
}

async function destinationLabel(destinationId) {
  const destination = await getDestinationById(destinationId);
  return destination?.label || "Discord";
}

function isValidWebhookUrl(url) {
  return WEBHOOK_URL_PATTERN.test(String(url || "").trim());
}

function createDestinationId(label, existingIds) {
  const base = slugifyId(label);
  if (!existingIds.has(base)) return base;
  let index = 2;
  while (existingIds.has(`${base}-${index}`)) index += 1;
  return `${base}-${index}`;
}

  // --- 10-preferences.js ---
const PREFERENCES_STORAGE_KEY = "tds-preferences";

const DEFAULT_PREFERENCES = {
  alwaysShowPreview: true
};

function sanitizePreferences(value) {
  const input = value && typeof value === "object" ? value : {};
  return {
    alwaysShowPreview: input.alwaysShowPreview !== false
  };
}

async function loadPreferences() {
  const stored = await storageGet(PREFERENCES_STORAGE_KEY, null);
  return sanitizePreferences(stored);
}

async function savePreferences(preferences) {
  const sanitized = sanitizePreferences(preferences);
  await storageSet(PREFERENCES_STORAGE_KEY, sanitized);
  return sanitized;
}

